/* SEARCH BAR STYLINGS */
form.am-search--form {
  --am-height: 3rem;
  background: #C0DDF1;
  width: 100%;
  display: flex;
  flex-flow: row nowrap;
  justify-content: stretch;
  align-items: center;
  gap: 0;
}

/* Hidden label (accessibility) */
form.am-search--form label {
  border: 0;
  clip-path: inset(50%);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
}

/* Input field */
form.am-search--form input[type="search"] {
  flex: 1;
  background: none;
  padding: 0.25rem 1rem;
  font: 600 16px Montserrat;
  border: none;
  height: var(--am-height);
}

/* Placeholder styling */
form.am-search--form input[type="search"]::placeholder {
  color: #132A50;
  opacity: 1;
}

form.am-search--form input[type="search"]:focus {
/*  outline: none;
  box-shadow: 0 0 0 2px #132A50; */

  outline: none;
  border: none;
  box-shadow: none;

}

/* Button styling */
form.am-search--form button {
  margin: 0.5rem 0.5rem 0.5rem 0;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  background: var(--am-searchBar_button--color);
  cursor: pointer;
  border: none;
}


