form.am-search--form button {
  margin: 0.5rem 0.5rem 0.5rem 0;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  background: var(--am-searchBar_button--color);
  cursor: pointer;
  border: none;
}


